function validate(input) {
  const [{ Product = [], Sales = [] }] = input;
  const ids = new Set();
  for (const [id] of Product) {
    if (id === null) return 'Every product needs a product_id.';
    if (ids.has(id)) return `product_id ${id} appears twice in Product.`;
    ids.add(id);
  }
  for (const [, productId, , date] of Sales) {
    if (!ids.has(productId)) return `Sales names product_id ${productId}, which is not in Product.`;
    if (date === null) return 'Every sale needs a sale_date.';
  }
  return null;
}

