function generate(rand, size) {
  const names = ['S8', 'G4', 'iPhone', 'Pixel', 'Nokia', 'Moto', 'Xperia', 'S8'];
  const dates = ['2018-12-31', '2019-01-01', '2019-01-21', '2019-02-17', '2019-03-31', '2019-04-01', '2019-06-02', '2020-02-10', '2018-03-15'];
  const inQuarter = ['2019-01-01', '2019-01-21', '2019-02-17', '2019-03-08', '2019-03-31'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const productCount = small ? Math.floor(rand() * 7) : 500;
  const saleCount = productCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Product = [], Sales = [];
  // Some products sell only inside the quarter, the rest anywhere, so both outcomes are common.
  const quarterOnly = [];
  for (let id = 1; id <= productCount; id++) {
    Product.push([id, pick(names), 100 * (1 + Math.floor(rand() * 15))]);
    quarterOnly.push(rand() < 0.4);
  }
  for (let i = 0; i < saleCount; i++) {
    if (small && i > 0 && rand() < 0.15) { Sales.push([...Sales[i - 1]]); continue; }
    const productId = 1 + Math.floor(rand() * productCount);
    const date = quarterOnly[productId - 1] ? pick(inQuarter) : pick(dates);
    const quantity = 1 + Math.floor(rand() * 3);
    Sales.push([1 + Math.floor(rand() * 4), productId, 1 + Math.floor(rand() * 6), date, quantity, quantity * Product[productId - 1][2]]);
  }
  return [{ Product, Sales }];
}
